{"query": "import os

# Broader search across common locations
search_roots = ['/tmp', '/home', '/mnt', '/data', '/workspace', '/root', os.getcwd()]
found = []
for base in search_roots:
    if os.path.exists(base):
        for root, dirs, files in os.walk(base):
            # avoid walking too deep into system caches
            for f in files:
                if f.lower().endswith('.csv'):
                    found.append(os.path.join(root, f))

print(f"Total CSV files found: {len(found)}")
for path in found[:50]:
    print(" -", path)"}

